import React, { useState } from 'react';
import {
  loginRequest,
  registerRequest,
  getErrorMessage,
  AuthUserPublic
} from '../api';

type Mode = 'login' | 'register';

interface LoginPanelProps {
  onLoggedIn: (user: AuthUserPublic) => void;
  onGuest: () => void;
}

export const LoginPanel: React.FC<LoginPanelProps> = ({ onLoggedIn, onGuest }) => {
  const [mode, setMode] = useState<Mode>('login');
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [displayName, setDisplayName] = useState('');
  const [submitting, setSubmitting] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError(null);
    setSubmitting(true);
    try {
      if (mode === 'login') {
        const data = await loginRequest(username.trim(), password);
        onLoggedIn(data.user);
      } else {
        const data = await registerRequest(username.trim(), password, displayName.trim() || undefined);
        onLoggedIn(data.user);
      }
    } catch (err) {
      setError(getErrorMessage(err));
    } finally {
      setSubmitting(false);
    }
  };

  return (
    <div className="login-overlay">
      <div className="login-card">
        <div className="login-brand">
          <span className="login-brand-icon" aria-hidden="true">
            🌿
          </span>
        </div>
        <h2 className="login-title">心理港湾 · 高校心理健康平台</h2>
        <p className="login-desc">学生登录进入咨询端；辅导员/管理员进入学校管理端。也可游客体验学生功能。</p>
        <div className="login-tabs">
          <button
            type="button"
            className={mode === 'login' ? 'active' : ''}
            onClick={() => { setMode('login'); setError(null); }}
          >
            登录
          </button>
          <button
            type="button"
            className={mode === 'register' ? 'active' : ''}
            onClick={() => { setMode('register'); setError(null); }}
          >
            注册新账号
          </button>
        </div>

        <form onSubmit={handleSubmit} className="login-form">
          <label>
            <span>用户名（3～24 位，字母/数字/下划线/中文）</span>
            <input
              type="text"
              value={username}
              autoComplete={mode === 'login' ? 'username' : 'new-username'}
              onChange={(e) => setUsername(e.target.value)}
              placeholder={mode === 'login' ? '例如 demo' : '起一个用户名'}
            />
          </label>
          {mode === 'register' && (
            <label>
              <span>显示昵称（可选）</span>
              <input
                type="text"
                value={displayName}
                onChange={(e) => setDisplayName(e.target.value)}
                placeholder="在界面顶部显示的名字"
              />
            </label>
          )}
          <label>
            <span>{mode === 'login' ? '密码' : '密码（不少于 6 位）'}</span>
            <input
              type="password"
              value={password}
              autoComplete={mode === 'login' ? 'current-password' : 'new-password'}
              onChange={(e) => setPassword(e.target.value)}
              placeholder={mode === 'login' ? '密码' : '设置密码'}
            />
          </label>
          {error && <div className="login-error">{error}</div>}
          <button type="submit" className="login-submit" disabled={submitting}>
            {submitting ? '请稍候…' : mode === 'login' ? '登录' : '注册并登录'}
          </button>
        </form>

        <p className="login-hint">
          学生端：<code>demo</code> / <code>demo123</code>
          {' · '}
          学校端：<code>counselor</code> / <code>counselor123</code> 或 <code>admin</code> / <code>admin123</code>
        </p>

        <button type="button" className="login-guest" onClick={onGuest}>
          暂不登录，游客体验（数据仅存本机浏览器）
        </button>
      </div>
    </div>
  );
};
